    msg += "\n";
    if (optimized) msg += "_Orden optimizado desde tu ubicacion actual (vecino mas cercano)._\n";
    let counter = 1;
    grupos.forEach((g, gi) => {
      const url = buildRouteMapsUrl(g, gi === 0 ? originLatLon : null);
      const label = grupos.length > 1 ? "TRAMO " + (gi + 1) + "/" + grupos.length + " (" + g.length + " tiendas)" : "Tiendas (" + g.length + ")";
      msg += "\n*" + label + "*\n";
      g.forEach((t) => {
        msg += counter + ") " + t.nombre + " - " + t.localidad + "\n";
        counter++;
      });
      msg += "Maps: " + url + "\n";
    });
    if (fuzzyCount > 0) {
      msg += "\n_AVISO: " + fuzzyCount + " tienda(s) sin GPS preciso ni direccion cargada. Maps las busca por nombre &mdash; chequea que caigan en el lugar correcto._";
    }
    if (grupos.length > 1) {
      msg += "\n_Cuando termines el TRAMO 1, abri el link del TRAMO 2 (y asi) para continuar desde donde estes._";
    }
