  async function runRendGastoOcr(isManualRetry) {
    if (!rdGastoFoto) {
      alert("Primero subi una foto del ticket.");
      return;
    }
    const statusEl = document.getElementById("rd-ocr-status");
    if (statusEl) {
      statusEl.innerHTML = '<div style="background:#dbeafe;border:1px solid #93c5fd;border-radius:5px;padding:8px 10px;font-size:11px;color:#1e40af;display:flex;align-items:center;gap:8px"><span class="ocr-spinner"></span>Analizando ticket con IA...</div>';
      statusEl.style.display = "";
    }
    try {
      const data = await extractTicketDataWithGemini(rdGastoFoto);
      fillRendGastoFormFromOcr(data);
      if (statusEl) {
        statusEl.innerHTML = '<div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:5px;padding:8px 10px;font-size:11px;color:#78350f"><b>&#9888; Revisa los campos</b> autocompletados antes de enviar. La IA puede equivocarse, sobre todo en montos, numero de ticket y descripcion. <button type="button" onclick="reRunRendGastoOcr()" style="background:#0891b2;color:#fff;border:none;border-radius:3px;padding:3px 8px;font-size:10px;font-weight:800;cursor:pointer;margin-left:6px">Re-analizar</button></div>';
      }
      showSyncTag("Campos autocompletados");
    } catch (e) {
      console.error("OCR error", e);
      if (statusEl) {
        statusEl.innerHTML = '<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:5px;padding:8px 10px;font-size:11px;color:#991b1b"><b>No se pudieron extraer los datos.</b> Comple\xED el form manualmente.<br><span style="font-size:10px;opacity:.8">Detalle: ' + escapeHtml(String(e.message || e).slice(0, 120)) + '</span><button type="button" onclick="reRunRendGastoOcr()" style="background:#0891b2;color:#fff;border:none;border-radius:3px;padding:3px 8px;font-size:10px;font-weight:800;cursor:pointer;margin-left:6px">Reintentar</button></div>';
      }
      if (isManualRetry) alert("OCR fallo: " + (e.message || e));
    }
  }
