  window.bulkImportSapClientes = function() {
    if (userRole !== "admin") return;
    const txt = prompt(
      "Pega aqui dos columnas (Tienda<TAB>Codigo_SAP o Tienda,Codigo_SAP) - una linea por tienda.\nIgnora encabezado si lo incluis.",
      ""
    );
    if (!txt) return;
    const lines = txt.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
    let ok = 0, skip = 0;
    (async () => {
      for (const line of lines) {
        const parts = line.split(/[\t,;]/).map((s) => s.trim());
        if (parts.length < 2) {
          skip++;
          continue;
        }
        const name = parts[0], code = parts[1];
        if (!name || !code) {
          skip++;
          continue;
        }
        const docId = sapNorm(name).replace(/[^A-Z0-9]/g, "_").slice(0, 1400);
        if (!docId) {
          skip++;
          continue;
        }
        try {
          await fbDb.collection("sap_clients").doc(docId).set(
            {
              clientName: name,
              sapCode: code,
              updatedBy: currentUser ? currentUser.email || currentUser.uid : "",
              updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            },
            { merge: true }
          );
          ok++;
        } catch (e) {
          console.error("bulk cli", e);
          skip++;
        }
      }
      alert("Importacion completada.\nGuardados: " + ok + "\nIgnorados: " + skip);
    })();
  };
