      html += '<div class="vc-meta">' + escapeHtml(v.tipo || "") + (v.local ? " - " + escapeHtml(v.local) : "") + " &middot; " + escapeHtml(v.tamano || "") + " &middot; Fidelidad " + escapeHtml(v.fidelidad || "") + " &middot; Relev " + (v.relevancia || 0) + "/5</div>";
