      info.innerHTML = "<b>" + escapeHtml(v.tienda || "?") + "</b>" + forma + "<br>" + escapeHtml(v.localidad || "") + " &middot; " + escapeHtml(titleCase(v.provincia || "")) + "<br>" + escapeHtml(v.mes || "") + " " + (v.anio || "") + " &middot; Estado actual: " + cur;
